package com.metabuild.modules.admin.dashboard.persistence;
import com.metabuild.modules.admin.dashboard.application.DashboardRepository;import java.time.OffsetDateTime;import java.util.*;import org.jooq.DSLContext;
public final class JooqDashboardRepository implements DashboardRepository {private final DSLContext db;public JooqDashboardRepository(DSLContext db){this.db=db;}
public Map<String,Object> overview(UUID user,int months){var company=db.fetchOne("select name,verified,industry,scale from mb_company where singleton_key=1");long[] members=period("mb_user","created_at",months,"deleted_at is null");long active=count("select count(*) from mb_user where deleted_at is null and status='ACTIVE'");long[] roles=period("mb_role","created_at",months,"deleted_at is null");long[] audits=period("mb_operation_log","created_at",months,"true");long pending=count("select count(*) from mb_inbox_message where recipient_user_id=? and approval_status='pending'",user);long done=count("select count(*) from mb_inbox_message where recipient_user_id=? and approval_status in ('approved','rejected')",user);long overdue=count("select count(*) from mb_inbox_message where recipient_user_id=? and approval_status='pending' and created_at<current_timestamp-interval '7 days'",user);var latest=db.fetch("select title,created_at,approval_status from mb_inbox_message where recipient_user_id=? and category='approval' order by created_at desc limit 3",user);return Map.of("company",Map.of("mark",initial(company==null?"M":company.get("name",String.class)),"name",company==null?"MetaBuilder":company.get("name",String.class),"status",company!=null&&Boolean.TRUE.equals(company.get("verified",Boolean.class))?"verified":"active","meta",company==null?"":Objects.toString(company.get("industry"),"")+" "+Objects.toString(company.get("scale"),"")),"metrics",Map.of("newMembers",metric(members),"activeUsers",metric(new long[]{active,active}),"newRoles",metric(roles),"auditLogs",metric(audits)),"trend",trend(months),"todo",Map.of("stats",Map.of("pending",stat(pending,"pending"),"done",stat(done,"done"),"overdue",stat(overdue,"overdue")),"items",Map.of("phone",item(latest,0),"onboard",item(latest,1),"interview",item(latest,2))));}
private long[] period(String table,String column,int months,String predicate){String sql="select count(*) filter(where "+column+">=current_timestamp-(?||' months')::interval),count(*) filter(where "+column+"<current_timestamp-(?||' months')::interval and "+column+">=current_timestamp-(?||' months')::interval) from "+table+" where "+predicate;var r=db.fetchOne(sql,months,months,months*2);return new long[]{r.get(0,Number.class).longValue(),r.get(1,Number.class).longValue()};}
private List<Map<String,Object>> trend(int months){return db.fetch("with months as (select generate_series(date_trunc('month',current_timestamp)-(?-1)*interval '1 month',date_trunc('month',current_timestamp),interval '1 month') m) select to_char(m,'YYYY-MM') as month_key,count(distinct l.user_id) as metric_value from months left join mb_login_log l on l.success and l.created_at>=m and l.created_at<m+interval '1 month' group by m order by m",months).map(r->Map.of("month",r.get("month_key",String.class),"value",r.get("metric_value",Number.class).longValue()));}
private long count(String sql,Object...args){return db.fetchOne(sql,args).get(0,Number.class).longValue();}private static Map<String,Object> metric(long[] values){long delta=values[0]-values[1];return Map.of("value",Long.toString(values[0]),"delta",Long.toString(Math.abs(delta)),"negative",delta<0);}private static Map<String,String> stat(long value,String label){return Map.of("value",Long.toString(value),"label",label);}private static Map<String,String> item(org.jooq.Result<org.jooq.Record> rows,int i){if(rows.size()<=i)return Map.of("title","No pending item","time","--","status","empty");var r=rows.get(i);return Map.of("title",r.get("title",String.class),"time",String.valueOf(r.get("created_at",OffsetDateTime.class)),"status",Objects.toString(r.get("approval_status"),"pending"));}private static String initial(String name){return name==null||name.isBlank()?"M":name.substring(0,1).toUpperCase(Locale.ROOT);}}
